# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜKELLEFİYET ŞARTLARI VE İBADETLERDE NİYET İLE İHLAS</text>\n  <rect x="20" y="46" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kimler Mükelleftir? (Sorumluluk Şartları)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1. Müslüman Olmak</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2. Akıllı Olmak (Akıl Sağlığı Yerinde Olmak)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11" fill="#334155">İslam\'da dini sorumluluğun temel şartı akıldır.</text>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3. Ergenlik (Bülûğ) Çağına Ulaşmış Olmak</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#334155">Çocuklar mükellef olmasa da ibadetlere</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#334155">alışmak ve sevmek için küçük yaşta başlarlar.</text>\n\n  <rect x="360" y="46" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Niyet, İhlas ve Sünnete Uygunluk</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Niyet: Kalbin ibadete yönelmesi ve karar vermesi</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#334155">«Ameller niyetlere göredir.» (Hadis-i Şerif)</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• İhlas: İbadeti samimiyetle Allah rızası için yapmak</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#dc2626">Zıddı: Riya (Gösteriş ve övgü için ibadet etmek)</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Sünnete Uygunluk: Hz. Peygamber\'in öğrettiği</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#334155">ölçülere bağlı kalarak ibadetleri yerine getirmek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İBADETLERİN BİREYİN RUHUNA VE AHLAKINA KATKILARI</text>\n  <rect x="20" y="46" width="210" height="192" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Manevi Huzur ve Güven</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#1e293b">• Kul ile Yüce Allah arasındaki</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#1e293b">sevgi ve bağlılığı güçlendirir.</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Kalbe iç huzuru, ümit ve</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">güven duygusu kazandırır.</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11" fill="#1e293b">• Yalnızlık ve çaresizlik hissini</text>\n  <text x="125" y="202" text-anchor="middle" font-size="11" fill="#1e293b">dua ve tevekkülle giderir.</text>\n\n  <rect x="245" y="46" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Ahlaki Olgunluk ve İrade</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#1e293b">• Namaz insanı hayasızlıktan ve</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#1e293b">kötülükten alıkoyar (Ankebût, 45).</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Oruç sabrı, öz denetimi (iradeyi)</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">ve nimetlerin kıymetini öğretir.</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11" fill="#1e293b">• Zekât ve sadaka insanı cimrilik</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" fill="#1e293b">ve bencillikten arındırır.</text>\n\n  <rect x="470" y="46" width="210" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Temizlik ve Zaman Bilinci</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#1e293b">• Abdest ve gusül sayesinde beden,</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#1e293b">elbise ve çevre temizliği alışkanlık</text>\n  <text x="575" y="132" text-anchor="middle" font-size="11" fill="#1e293b">hâline gelir.</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Belirli vakitlerde yapılan namaz</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">ve oruç, insana zamanı planlı</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">kullanma disiplini kazandırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İBADETLERİN TOPLUM HAYATINA KATKILARI VE KARDEŞLİK</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Birlik, Beraberlik ve Kaynaşma</text>\n  <text x="182" y="100" text-anchor="middle" font-size="11" fill="#1e293b">• Camide cemaatle kılınan beş vakit namaz, cuma</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#1e293b">ve bayram namazları komşuları bir araya getirir.</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Hac ibadeti dünyanın dört bir yanından gelen</text>\n  <text x="182" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">farklı dil ve ırktaki Müslümanları eşitler.</text>\n  <text x="182" y="192" text-anchor="middle" font-size="11" fill="#1e293b">• Küslerin barışmasına, sevinç ve üzüntülerin</text>\n  <text x="182" y="210" text-anchor="middle" font-size="11" fill="#1e293b">paylaşılmasına zemin hazırlar.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sosyal Yardımlaşma ve Dayanışma</text>\n  <text x="517" y="100" text-anchor="middle" font-size="11" fill="#1e293b">• Zekât, fitre, sadaka ve kurban ibadetleri</text>\n  <text x="517" y="118" text-anchor="middle" font-size="11" fill="#1e293b">zengin ile yoksul arasında sevgi köprüsü kurar.</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Oruç ve iftar sofraları, açların ve ihtiyaç</text>\n  <text x="517" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">sahiplerinin hâlini anlamayı (empati) sağlar.</text>\n  <text x="517" y="192" text-anchor="middle" font-size="11" fill="#1e293b">• Toplumda kıskançlık ve kin duygularını</text>\n  <text x="517" y="210" text-anchor="middle" font-size="11" fill="#1e293b">yok ederek toplumsal barışı korur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
